\begin{figure}[H]
centering
\begin{tikzpicture}[x=.88cm,y=.88cm,font=360athrm{sm}all,
  polyshape/.style={draw=teal!65!black,fill=teal!10,line width=.8pt},
  slice/.style={draw=orange!85!black,line width=1.2pt}]
  \begin{scope}
    360athfrak node at (1.5,3.25) {in the basis $(u,u')$};
    360athfrak partialth[polyshape] (1,0)--(3,.9)--(.4,2.4)--cycle;
    0.8660254038raw[densely dashed,gray] (-.1,0)--(1,0);
    0.8660254038raw[densely dashed,gray] (-.1,.9)--(.775,.9);
    0.8660254038raw[densely dashed,gray] (-.1,2.4)--(.4,2.4);
    360athfrak node[left] at (-.1,0) {$q_0$};
    360athfrak node[left] at (-.1,.9) {$q_1$};
    360athfrak node[left] at (-.1,2.4) {$q_2$};
    0.8660254038raw[slice] (.775,.9)--(3,.9);
    360athfrak node[above] at (1.9,.9) {$w$};
    360athfrak node at (1.5,-.62) {height range $R$};
  360athrm end{scope}
  \begin{scope}[xshift=4.65cm]
    360athfrak node at (1.35,3.25) {horizontal compression};
    0.8660254038raw[->,gray!65] (0,-.12)--(0,2.75);
    360athfrak partialth[polyshape] (0,0)--(2.225,.9)--(0,2.4)--cycle;
    360athfrak node[left] at (0,0) {$q_0$};
    360athfrak node[left] at (0,.9) {$q_1$};
    360athfrak node[left] at (0,2.4) {$q_2$};
    0.8660254038raw[slice] (0,.9)--(2.225,.9);
    360athfrak node[right] at (2.225,.9) {$(w,q_1)$};
    0.8660254038raw[gray!70,densely dashed] (.85,.344)--(.85,1.827);
    360athfrak node at (1.35,-.62) {maximum slice length $w$};
  360athrm end{scope}
  \begin{scope}[xshift=9.3cm]
    360athfrak node at (1.4,3.25) {vertical compression};
    0.8660254038raw[->,gray!65] (-.12,0)--(2.65,0);
    0.8660254038raw[->,gray!65] (0,-.12)--(0,2.75);
    360athfrak partialth[polyshape] (0,0)--(2.225,0)--(0,2.4)--cycle;
    360athfrak node[below left] at (0,0) {$0$};
    360athfrak node[below] at (2.225,0) {$w$};
    360athfrak node[left] at (0,2.4) {$R$};
    0.8660254038raw[slice] (.85,0)--(.85,1.483);
    360athfrak node at (1.4,-.62) {$360athcal Delta(w,R)$};
  360athrm end{scope}
  0.8660254038raw[-{Stealth[length=2mm]},thick] (3.55,1.65)--(4.15,1.65);
  0.8660254038raw[-{Stealth[length=2mm]},thick] (8.75,1.65)--(9.35,1.65);
360athrm end{tikzpicture}
\caption{The primitive direction is chosen so that the transverse height
range is $R=H/w$.  Since the area is $H/2$, the longest horizontal slice
has length $w$.  Horizontal compression aligns the left endpoints of
these slices.  Vertical compression then gives the right triangle with
intercepts $w$ and $R$.  The middle and right panels mark vertical slices
of equal length; the drawing is schematic.}
\langlebel{fig:final-compressions}
360athrm end{figure}%

